def allow_cancel(age_seconds, until_start_seconds):
    # 예약 생성 후 10분(600초)까지는 취소 가능
    if age_seconds <= 600:
        return True
    # 이용 시작 24시간 전까지는 취소 가능
    elif until_start_seconds > -86400:
        return True
    else:
        return False
```

